## 🎯 Dans cette leçon

Le **panneau solaire** (photovoltaïque) transforme la lumière en courant continu. C'est la source idéale d'un capteur loin du réseau : station météo, suivi d'un champ ou d'un puits, alarme autonome.

À la fin de cette leçon, tu sauras :

- lire l'étiquette d'un panneau : Wc, Voc, Isc ;
- comprendre la courbe courant-tension et le point de puissance maximale ;
- calculer le rendement d'un panneau ;
- dimensionner un panneau et une batterie pour un capteur autonome ;
- mesurer la tension d'un panneau sans abîmer l'Arduino.

blocs.code:
// Leçon 5.5 — tension d'un panneau solaire (pont 10 k / 10 k sur A0)
const float RAPPORT = 2.0;   // (R1 + R2) / R2
const float VREF = 5.0;      // référence du convertisseur (V)

void setup() {
  Serial.begin(9600);
}

void loop() {
  int n = analogRead(A0);                    // 0 à 1023
  float u = n * VREF / 1023.0 * RAPPORT;     // en volts
  Serial.print("Panneau : ");
  Serial.print(u, 2);
  Serial.println(" V");
  delay(1000);
}

// Solution du mini-défi : panneau (A0) et lumière (A1) dans le traceur série
void setup() {
  Serial.begin(9600);
}

void loop() {
  float panneau = analogRead(A0) * 5.0 / 1023.0 * 2;   // en volts
  float lumiere = analogRead(A1) * 100.0 / 1023.0;     // en % (0 = noir)
  Serial.print("panneau_V:");  Serial.print(panneau, 2);
  Serial.print(" lumiere_pct:"); Serial.println(lumiere, 0);
  delay(60000);   // une mesure par minute
}

